mapper.select:
SELECT T.* FROM (SELECT W.*, C.METHODNAME, C.TESTMETHODBASIS, D.TESTCATEGORYDESC AS TESTCATEGORY, E.ORGNAME, F.TESTNAME FROM T_EMC_TEST_METHOD W LEFT JOIN T_EMC_METHOD C ON W.METHODID = C.ID LEFT JOIN T_EMC_TEST_CATEGORY D ON W.TESTCATEGORYID = D.ID LEFT JOIN T_CORE_ORG E ON W.ANALYSISORGID = E.ID LEFT JOIN T_EMC_TEST F ON W.TESTID = F.ID) T
AND NOT EXISTS (SELECT 1 FROM ${targetTable} TAR_ WHERE TAR_.${targetTestMethodIdColumn} = T.ID
AND TAR_.${targetFilterColumn} = #{targetFilterValue}
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
)
AND ID IN(${tmids})
ORDER BY
T.ID DESC
